package dev.chyken.assembl_ar.learning;
import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
public final class NeobotProgramTest {
    @Test public void generatedSketchUsesAuthoredPinsAndStopsAtEnd(){List<NeobotProgram.Block> all=new ArrayList<>();for(NeobotProgram.Kind k:NeobotProgram.Kind.values())all.add(new NeobotProgram.Block(k,160,500));String cpp=NeobotProgram.cpp(all);assertTrue(cpp.contains("A1A=5, A1B=9, B1A=6, B1B=10"));assertTrue(cpp.contains("TRIG=2, ECHO=4, LED_PIN=A1, SPEAKER=3"));assertTrue(cpp.contains("TRACK_LEFT=A2, TRACK_RIGHT=A3"));assertTrue(cpp.contains("drive(-160,-160)"));assertTrue(cpp.contains("pulseIn(ECHO, HIGH, 30000UL)"));assertTrue(cpp.contains("while (true) delay(1000)"));assertFalse(cpp.contains("initializer_list"));}
    @Test public void savedBlockDraftRoundTripsAndCorruptDraftFallsBack(){List<NeobotProgram.Block> blocks=NeobotProgram.starter();assertEquals(NeobotProgram.encode(blocks),NeobotProgram.encode(NeobotProgram.decode(NeobotProgram.encode(blocks))));assertEquals(2,NeobotProgram.decode("1;FORWARD,999,10").size());assertTrue(NeobotProgram.decode("1").isEmpty());}
    @Test public void simulationPreservesMotorStateAcrossWaitAndStopsAtEnd(){List<NeobotProgram.Block> blocks=Arrays.asList(new NeobotProgram.Block(NeobotProgram.Kind.FORWARD,255,500),new NeobotProgram.Block(NeobotProgram.Kind.WAIT,0,500));ProgramSimulator s=new ProgramSimulator(blocks);s.advance(500);assertFalse(s.finished());assertEquals(117.5,s.y(),.01);s.advance(500);assertTrue(s.finished());assertEquals(85,s.y(),.01);s.advance(500);assertEquals(85,s.y(),.01);}
    @Test public void turningAndLedAffectSimulationWithoutHardware(){ProgramSimulator s=new ProgramSimulator(Arrays.asList(new NeobotProgram.Block(NeobotProgram.Kind.LED_ON,0,50),new NeobotProgram.Block(NeobotProgram.Kind.LEFT,255,500)));s.advance(550);assertTrue(s.finished());assertTrue(s.led());assertTrue(s.heading()< -Math.PI/2);assertEquals(150,s.x(),.01);}
}
